/**
 * Sunday Arena problems (generated by ai/generate_contest.py).
 * Admin endpoints live under /admin/arena/problems, student endpoints under /arena.
 * XP and hint penalties are always computed by the backend.
 */

import { apiRequest } from "./api.js";

export const ARENA_XP_TIERS = [25, 50, 75, 100, 125, 150];
export const HINT_PENALTY_RATE = 0.25;

/** Tier index (0-5) doubles as the generator's difficulty index. */
export const ARENA_TIER_LABELS = [
  "Very Easy",
  "Easy",
  "Easy-Medium",
  "Medium",
  "Medium-Hard",
  "Hard",
];

/** Formats XP keeping meaningful fractions: 75 -> "75", 18.75 -> "18.75", 112.5 -> "112.5". */
export function formatXp(value) {
  const num = Number(value) || 0;
  return Number.isInteger(num)
    ? num.toLocaleString("en-US")
    : num.toLocaleString("en-US", { maximumFractionDigits: 2 });
}

/** Display-only preview of the backend rule; the backend value is authoritative. */
export function xpAfterHint(problemXp) {
  return Math.round(problemXp * (1 - HINT_PENALTY_RATE) * 100) / 100;
}

// ---------------------------------------------------------------------------
// ADMIN
// ---------------------------------------------------------------------------

export async function fetchAdminArenaProblems(status) {
  const query = status && status !== "ALL" ? `?status=${encodeURIComponent(status)}` : "";
  return apiRequest(`/admin/arena/problems${query}`);
}

export async function fetchAdminArenaProblem(id) {
  return apiRequest(`/admin/arena/problems/${id}`);
}

/**
 * Generates a full story contest: 6 connected problems, one per XP tier
 * (25 -> 150), saved together as one DRAFT set.
 * @param {{ description: string }} payload
 */
export async function generateArenaContest({ description }) {
  return apiRequest("/admin/arena/contests/generate", {
    method: "POST",
    body: JSON.stringify({ description }),
  });
}

/** Regenerates all 6 problems of a set in place (refused once students attempted it). */
export async function regenerateArenaContest(batchId, { description } = {}) {
  return apiRequest(`/admin/arena/contests/${batchId}/regenerate`, {
    method: "POST",
    body: JSON.stringify(description ? { description } : {}),
  });
}

/** Publishes the set; the server keeps the existing window or defaults to next Sunday. */
export async function publishArenaContest(batchId, { startsAt, endsAt } = {}) {
  return apiRequest(`/admin/arena/contests/${batchId}/publish`, {
    method: "POST",
    body: JSON.stringify({
      ...(startsAt ? { startsAt } : {}),
      ...(endsAt ? { endsAt } : {}),
    }),
  });
}

/** Sets the live window (ISO strings). The server enforces it for submissions. */
export async function scheduleArenaContest(batchId, { startsAt, endsAt } = {}) {
  // No times -> the server resets to the weekly slot (next Sunday 17:00-20:00).
  return apiRequest(`/admin/arena/contests/${batchId}/schedule`, {
    method: "PATCH",
    body: JSON.stringify({
      ...(startsAt ? { startsAt } : {}),
      ...(endsAt ? { endsAt } : {}),
    }),
  });
}

/** All contests (current + archive) with stage, window and participants. */
export async function fetchAdminArenaContests() {
  return apiRequest("/admin/arena/contests");
}

export async function unpublishArenaContest(batchId) {
  return apiRequest(`/admin/arena/contests/${batchId}/unpublish`, { method: "POST" });
}

export async function deleteArenaContest(batchId) {
  return apiRequest(`/admin/arena/contests/${batchId}`, { method: "DELETE" });
}

export async function updateArenaProblem(id, updates) {
  return apiRequest(`/admin/arena/problems/${id}`, {
    method: "PATCH",
    body: JSON.stringify(updates),
  });
}

export async function setArenaProblemXp(id, xp) {
  return apiRequest(`/admin/arena/problems/${id}/xp`, {
    method: "PATCH",
    body: JSON.stringify({ xp: Number(xp) }),
  });
}

export async function publishArenaProblem(id) {
  return apiRequest(`/admin/arena/problems/${id}/publish`, { method: "POST" });
}

export async function unpublishArenaProblem(id) {
  return apiRequest(`/admin/arena/problems/${id}/unpublish`, { method: "POST" });
}

export async function deleteArenaProblem(id) {
  return apiRequest(`/admin/arena/problems/${id}`, { method: "DELETE" });
}

// ---------------------------------------------------------------------------
// STUDENT
// ---------------------------------------------------------------------------

/** Problems of the current contest, or of a past one when contestId is given. */
export async function fetchArenaProblems(contestId) {
  return apiRequest(`/arena/problems${contestId ? `?contestId=${encodeURIComponent(contestId)}` : ""}`);
}

export async function fetchArenaProblem(id) {
  return apiRequest(`/arena/problems/${id}`);
}

export async function revealArenaHint(id) {
  return apiRequest(`/arena/problems/${id}/hint`, { method: "POST" });
}

export async function runArenaExamples(id, { code, language }) {
  return apiRequest(`/arena/problems/${id}/run`, {
    method: "POST",
    body: JSON.stringify({ code: String(code || ""), language }),
  });
}

export async function submitArenaSolution(id, { code, language }) {
  return apiRequest(`/arena/problems/${id}/submit`, {
    method: "POST",
    body: JSON.stringify({ code: String(code || ""), language }),
  });
}

export async function fetchMyArenaXp() {
  return apiRequest("/arena/me/xp");
}
